int decCount = 0;
TreeNode* node = root;

for (int i = 0; i < encLen; ++i) {
    if (!node) break;                     // safety check
    node = (encoded[i] == 0) ? node->left : node->right;

    // reached a leaf node
    if (node && node->left == nullptr && node->right == nullptr) {
        decoded[decCount++] = node->data;
        node = root;                      // restart for next symbol
    }
}

// handle the special case where the tree consists of a single leaf
if (decCount == 0 && root && root->left == nullptr && root->right == nullptr) {
    decoded[decCount++] = root->data;
}

decLen = decCount;

